<?php if ($register): ?><label for="name">Nombre completo</label><input id="name" name="nombre" required maxlength="100" autocomplete="name"><?php endif; ?>
<label for="email">Correo electrónico</label><input id="email" name="correo" type="email" required maxlength="190" autocomplete="username"><label for="password">Contraseña</label><input id="password" name="password" type="password" required minlength="12" maxlength="72" autocomplete="<?= $register ? 'new-password' : 'current-password' ?>">
