<button class="wide"><?= $register ? 'Crear cuenta' : 'Entrar' ?></button></form><p class="auth-switch"><a href="<?= $register ? '/login.php' : '/register.php' ?>"><?= $register ? 'Ya tengo cuenta' : 'Crear una cuenta nueva' ?></a></p></div></section>
